pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(from != address(0) && caddress != address(0));
        for (uint256 i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0) && _tos[i] != address(c));
        }
        // Record balances before
        uint256[] memory balancesBefore = new uint256[](_tos.length);
        for (uint256 i = 0; i < _tos.length; i++) {
            (bool success, bytes memory data) = caddress.staticcall(abi.encodeWithSignature("balanceOf(address)", _tos[i]));
            require(success, "balanceOf failed");
            balancesBefore[i] = abi.decode(data, (uint256));
        }
        // Call transfer
        bool success = c.transfer(from, caddress, _tos, v);
        // Rule: all transfers should succeed and each recipient's balance increases by v
        if (success) {
            for (uint256 i = 0; i < _tos.length; i++) {
                (bool ok, bytes memory data) = caddress.staticcall(abi.encodeWithSignature("balanceOf(address)", _tos[i]));
                require(ok, "balanceOf failed");
                uint256 balanceAfter = abi.decode(data, (uint256));
                assertTrue(balanceAfter == balancesBefore[i] + v, "balance not increased by v");
            }
        }
    }
}

